def obj(properties):
    return {'type': 'object', 'properties': properties, 'required': list(properties), 'additionalProperties': False}


def tool_definitions():
    ledger = deepcopy(LEDGER)
    report = deepcopy(REPORT)
    input_defs = ledger.pop('$defs', {})
    output_defs = report.pop('$defs', {})
    for schema in (ledger, report):
        schema.pop('$id', None)
        schema.pop('$schema', None)
    common = {'schema_version': {'const': 1}, 'scope': {'const': 'bounded_dependency_applicability'},
              'formal_proof': {'const': False}, 'runtime_goal_acceptance': {'const': False},
              'proof_accepted': {'const': False}, 'truth_assessment': {'const': 'not_assessed'}}
    success = obj({**common, 'status': {'const': 'success'}, 'result': report})
    error = obj({**common, 'status': {'const': 'error'}, 'error': obj({
        'code': {'type': 'string'}, 'path': {'type': 'string'}, 'message': {'type': 'string'}})})
    output = obj({'tool': {'const': 'replay_claim_applicability'},
                  'assessment': {'enum': ['claim_dependency_applicability_replayed', 'tool_error']},
                  'formal_proof': {'const': False}, 'runtime_goal_acceptance': {'const': False},
                  'receipt': {'oneOf': [success, error]}})
    output['allOf'] = [{'if': {'properties': {'receipt': {'properties': {'status': {'const': 'success'}}}}},
                        'then': {'properties': {'assessment': {'const': 'claim_dependency_applicability_replayed'}}},
                        'else': {'properties': {'assessment': {'const': 'tool_error'}}}}]
    draft = 'https://json-schema.org/draft/2020-12/schema'
    return [{'name': 'replay_claim_applicability', 'readOnly': True,
             'description': 'Replay explicit exact-revision all-required dependencies and ordered withdrawals, revisions, '
             'and unchecked refutation reports. Return current applicability blockers and canonical witness paths, '
             'not a certificate, mathematical truth judgment, evidence acceptance, or independent verification. '
             'Authored statuses and counterexample reports remain unverified. No automatic repinning or alternative-proof semantics. '
             'Hashes bind bytes, not authenticity; artifact bytes are never fetched. '
             'At most 64 records, 64 events and 256 current edges; fixed explanation budgets may reject otherwise valid graphs. '
             'Bridge retains 65536 input bytes including envelope, 1048576 output bytes, 16384 JSON nodes, and no '
             'caller limits, paths, code, commands, network, model calls, formal proof or runtime goal acceptance.',
             'inputSchema': {'$schema': draft, **obj({'ledger': ledger}), '$defs': input_defs},
             'outputSchema': {'$schema': draft, **output, '$defs': output_defs}}]
